package net.zartra.gui;
import java.util.UUID;
final class ActionEntry { String id=UUID.randomUUID().toString(); String type="MESSAGE"; String value=""; int order; long delay; double chance=100D; boolean enabled=true; boolean stopOnFailure; ConditionSet.Mode conditionMode=ConditionSet.Mode.AND; String conditionFailureMessage=""; final java.util.List<ConditionEntry> conditions=new java.util.ArrayList<ConditionEntry>(); final java.util.List<ActionEntry> successActions=new java.util.ArrayList<ActionEntry>(); final java.util.List<ActionEntry> failureActions=new java.util.ArrayList<ActionEntry>(); ActionEntry copy(){return copy(false);} ActionEntry duplicate(){return copy(true);} private ActionEntry copy(boolean fresh){ActionEntry x=new ActionEntry();if(!fresh)x.id=id;x.type=type;x.value=value;x.order=order;x.delay=delay;x.chance=chance;x.enabled=enabled;x.stopOnFailure=stopOnFailure;x.conditionMode=conditionMode;x.conditionFailureMessage=conditionFailureMessage;for(ConditionEntry c:conditions)x.conditions.add(fresh?c.duplicate():c.copy());for(ActionEntry z:successActions)x.successActions.add(z.copy());for(ActionEntry z:failureActions)x.failureActions.add(z.copy());return x;} }
